use verus::prelude::*;

// Computes the minimum number of strength‐damage attacks
// needed to bring an enemy from `health` down to zero or below.
// Ceiling division: ⌈health / strength⌉ = (health + strength − 1) / strength
#[requires(health >= 0)]        // cannot have negative health
#[requires(strength > 0)]       // must do at least 1 damage per turn
#[ensures(result >= 0)]         // non‐negative number of turns
#[ensures(result * (strength as i64) >= health as i64)]
// if we need at least one turn, then one turn less is insufficient
#[ensures(
    if result > 0 {
        (result - 1) * (strength as i64) < (health as i64)
    } else {
        // result == 0 exactly when health == 0
        health == 0
    }
)]
fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    let h = health as i64;
    let s = strength as i64;
    let result = (h + s - 1) / s;
    // verify the ensures above by simple assertions
    assert(result >= 0);
    assert(result * s >= h);
    assert(if result > 0 { (result - 1) * s < h } else { h == 0 });
    result
}

// Given:
//   a = Takahashi's health
//   b = Aoki's strength
//   c = Aoki's health
//   d = Takahashi's strength
// We say “Yes” exactly when Takahashi can defeat Aoki
// in no more turns than Aoki can defeat Takahashi.
#[requires(a >= 0)]
#[requires(b > 0)]
#[requires(c >= 0)]
#[requires(d > 0)]
#[ensures(|res: String|
    // res == "Yes"  ⇔  Takahashi_turns ≤ Aoki_turns
    if exec_turns_to_defeat(c, b) <= exec_turns_to_defeat(a, d) {
        res == "Yes".to_string()
    } else {
        res == "No".to_string()
    }
)]
fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // turns for Takahashi to defeat Aoki
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // turns for Aoki to defeat Takahashi
    let aoki_turns     = exec_turns_to_defeat(a, d);

    let ans = if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    };

    // supporting assertions to help the verifier see the postcondition
    if takahashi_turns <= aoki_turns {
        assert(ans == "Yes".to_string());
    } else {
        assert(ans == "No".to_string());
    }

    ans
}

